package com.osrstracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("osrs-tracker")
public interface OsrsTrackerConfig extends Config
{
	@ConfigItem(
		keyName = "enableSync",
		name = "Enable XP Sync",
		description = "Send XP snapshots to the OSRS Tracker backend",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean enableSync()
	{
		return false;
	}

	@ConfigItem(
		keyName = "syncIntervalMinutes",
		name = "Sync interval (minutes)",
		description = "How often to send XP snapshots (minimum: 1)"
	)
	default int syncIntervalMinutes()
	{
		return 5;
	}
}

package com.osrstracker;

import com.osrstracker.model.F2pSkill;
import net.runelite.client.ui.PluginPanel;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.EnumMap;
import java.util.Map;

public class OsrsTrackerPanel extends PluginPanel
{
	private final JLabel usernameLabel = new JLabel("Not logged in", SwingConstants.CENTER);
	private final Map<F2pSkill, JLabel> xpLabels = new EnumMap<>(F2pSkill.class);

	OsrsTrackerPanel()
	{
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		usernameLabel.setForeground(Color.WHITE);
		add(usernameLabel, BorderLayout.NORTH);

		JPanel skillsPanel = new JPanel(new GridLayout(0, 1, 0, 2));
		skillsPanel.setBackground(getBackground());

		for (F2pSkill skill : F2pSkill.values())
		{
			JLabel label = new JLabel(skill.key + ": —");
			label.setForeground(Color.LIGHT_GRAY);
			xpLabels.put(skill, label);
			skillsPanel.add(label);
		}

		add(skillsPanel, BorderLayout.CENTER);
	}

	void setUsername(String username)
	{
		usernameLabel.setText(username != null ? username : "Not logged in");
	}

	void updateSkill(F2pSkill skill, int xp, int level)
	{
		JLabel label = xpLabels.get(skill);
		if (label != null)
		{
			label.setText(String.format("%s: Lv %d (%,d xp)", skill.key, level, xp));
		}
	}

	void reset()
	{
		usernameLabel.setText("Not logged in");
		xpLabels.values().forEach(l -> l.setText(l.getText().split(":")[0] + ": —"));
	}
}

package com.osrstracker;

import com.google.inject.Provides;
import com.osrstracker.api.ApiClient;
import com.osrstracker.api.SkillSnapshot;
import com.osrstracker.model.F2pSkill;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Response;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
	name = "OSRS Tracker",
	description = "Tracks F2P skill XP and recommends training methods",
	tags = {"xp", "skills", "tracker", "f2p"}
)
public class OsrsTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OsrsTrackerConfig config;

	@Inject
	private ApiClient apiClient;

	private OsrsTrackerPanel panel;
	private NavigationButton navButton;

	private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
	private ScheduledFuture<?> syncTask;

	// Escritos no client thread via eventos, lidos no executor thread em sendSnapshot.
	// volatile garante visibilidade dos campos simples; synchronized guarda os mapas.
	private volatile String cachedUsername;
	private volatile String cachedAccountType;
	private final Map<F2pSkill, Long> xpCache = new EnumMap<>(F2pSkill.class);
	private final Map<F2pSkill, Integer> levelCache = new EnumMap<>(F2pSkill.class);

	@Override
	protected void startUp()
	{
		panel = new OsrsTrackerPanel();

		BufferedImage icon = ImageUtil.loadImageResource(OsrsTrackerPlugin.class, "/icon.png");
		if (icon == null)
		{
			icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		}

		navButton = NavigationButton.builder()
			.tooltip("OSRS Tracker")
			.icon(icon)
			.panel(panel)
			.priority(5)
			.build();

		clientToolbar.addNavigation(navButton);
		log.info("OSRS Tracker started");
	}

	@Override
	protected void shutDown()
	{
		if (syncTask != null)
		{
			syncTask.cancel(false);
			syncTask = null;
		}
		executor.shutdownNow();
		clientToolbar.removeNavigation(navButton);
		panel = null;

		synchronized (xpCache)
		{
			xpCache.clear();
		}
		synchronized (levelCache)
		{
			levelCache.clear();
		}

		cachedUsername = null;
		cachedAccountType = null;
		log.info("OSRS Tracker stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			if (client.getLocalPlayer() != null)
			{
				cachedUsername = client.getLocalPlayer().getName();
			}
			cachedAccountType = client.getAccountType().name();

			SwingUtilities.invokeLater(() -> panel.setUsername(cachedUsername));
			scheduleSyncTask();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			cancelSyncTask();
			cachedUsername = null;
			cachedAccountType = null;

			synchronized (xpCache)
			{
				xpCache.clear();
			}
			synchronized (levelCache)
			{
				levelCache.clear();
			}

			SwingUtilities.invokeLater(() -> panel.reset());
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		F2pSkill skill = F2pSkill.fromSkill(event.getSkill());
		if (skill == null)
		{
			return;
		}

		synchronized (xpCache)
		{
			xpCache.put(skill, (long) event.getXp());
		}
		synchronized (levelCache)
		{
			levelCache.put(skill, event.getLevel());
		}

		final F2pSkill finalSkill = skill;
		final int xp = event.getXp();
		final int level = event.getLevel();
		SwingUtilities.invokeLater(() -> panel.updateSkill(finalSkill, xp, level));
	}

	private void scheduleSyncTask()
	{
		cancelSyncTask();
		int intervalMinutes = Math.max(1, config.syncIntervalMinutes());
		syncTask = executor.scheduleAtFixedRate(
			this::sendSnapshot,
			intervalMinutes,
			intervalMinutes,
			TimeUnit.MINUTES
		);
	}

	private void cancelSyncTask()
	{
		if (syncTask != null)
		{
			syncTask.cancel(false);
			syncTask = null;
		}
	}

	private void sendSnapshot()
	{
		if (!config.enableSync())
		{
			return;
		}

		String username = cachedUsername;
		String accountType = cachedAccountType;
		if (username == null || accountType == null)
		{
			return;
		}

		final Map<F2pSkill, Long> xpSnapshot;
		final Map<F2pSkill, Integer> levelSnapshot;

		synchronized (xpCache)
		{
			xpSnapshot = new EnumMap<>(xpCache);
		}
		synchronized (levelCache)
		{
			levelSnapshot = new EnumMap<>(levelCache);
		}

		Map<String, Long> skills = new HashMap<>();
		long totalXp = 0;
		int totalLevel = 0;

		for (F2pSkill skill : F2pSkill.values())
		{
			long xp = xpSnapshot.getOrDefault(skill, 0L);
			skills.put(skill.key, xp);
			totalXp += xp;
			totalLevel += levelSnapshot.getOrDefault(skill, 1);
		}

		skills.put("total_level", (long) totalLevel);
		skills.put("total_xp", totalXp);

		SkillSnapshot snapshot = new SkillSnapshot(username, accountType, skills);

		apiClient.sendSnapshot(snapshot, new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to send snapshot", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						log.debug("Snapshot response error: {}", response.code());
					}
				}
			}
		});
	}

	@Provides
	OsrsTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrsTrackerConfig.class);
	}
}

package com.osrstracker.api;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

import javax.inject.Inject;

@Slf4j
public class ApiClient
{
	static final String API_ENDPOINT = "https://xanlaynufesmyhryeewx.supabase.co/functions/v1/ingest-snapshot";

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	public void sendSnapshot(SkillSnapshot snapshot, Callback callback)
	{
		String json = gson.toJson(snapshot);
		RequestBody body = RequestBody.create(MediaType.get("application/json"), json);
		Request request = new Request.Builder()
			.url(API_ENDPOINT)
			.post(body)
			.build();
		okHttpClient.newCall(request).enqueue(callback);
	}
}

package com.osrstracker.api;

import java.util.Map;

public class SkillSnapshot
{
	public final String username;
	public final String account_type;
	public final Map<String, Long> skills;

	public SkillSnapshot(String username, String account_type, Map<String, Long> skills)
	{
		this.username = username;
		this.account_type = account_type;
		this.skills = skills;
	}
}

package com.osrstracker.model;

import net.runelite.api.Skill;

import java.util.EnumMap;
import java.util.Map;

public enum F2pSkill
{
	HITPOINTS(Skill.HITPOINTS, "hitpoints"),
	ATTACK(Skill.ATTACK, "attack"),
	STRENGTH(Skill.STRENGTH, "strength"),
	DEFENCE(Skill.DEFENCE, "defence"),
	RANGED(Skill.RANGED, "ranged"),
	PRAYER(Skill.PRAYER, "prayer"),
	MAGIC(Skill.MAGIC, "magic"),
	MINING(Skill.MINING, "mining"),
	SMITHING(Skill.SMITHING, "smithing"),
	FISHING(Skill.FISHING, "fishing"),
	COOKING(Skill.COOKING, "cooking"),
	FIREMAKING(Skill.FIREMAKING, "firemaking"),
	WOODCUTTING(Skill.WOODCUTTING, "woodcutting"),
	CRAFTING(Skill.CRAFTING, "crafting"),
	RUNECRAFT(Skill.RUNECRAFT, "runecraft");

	public final Skill runeliteSkill;
	public final String key;

	F2pSkill(Skill runeliteSkill, String key)
	{
		this.runeliteSkill = runeliteSkill;
		this.key = key;
	}

	private static final Map<Skill, F2pSkill> BY_SKILL = new EnumMap<>(Skill.class);

	static
	{
		for (F2pSkill f : values())
		{
			BY_SKILL.put(f.runeliteSkill, f);
		}
	}

	public static F2pSkill fromSkill(Skill skill)
	{
		return BY_SKILL.get(skill);
	}
}

